{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#FFF9F5;--card:#FFFFFF;--muted:#6b6b6b;--accent:#8bbf9f;--accent-2:#f2c57c;--glass:rgba(255,255,255,0.6);--shadow:0 6px 18px rgba(12,12,12,0.08);--radius:14px}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#222;background:linear-gradient(180deg,var(--bg),#fff 60%)}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px}
    nav a{margin:0 10px;color:#333;text-decoration:none;font-weight:600}
    .logo{display:flex;align-items:center;gap:12px}
    .logo .dot{width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));box-shadow:var(--shadow);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}

    .hero{padding:28px;border-radius:18px;margin:10px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.85),rgba(250,250,250,0.6));display:grid;grid-template-columns:1fr 420px;gap:26px;align-items:center}
    .hero h1{margin:0;font-size:28px}
    .hero p{color:var(--muted);margin-top:8px}

    .pattern-crest{width:100%;height:120px;border-radius:12px;background-image:url('assets/img/pattern.svg');background-repeat:repeat;opacity:.12}

    .controls{display:flex;align-items:center;gap:14px}
    .toggle{display:inline-flex;background:var(--card);padding:6px;border-radius:999px;box-shadow:var(--shadow)}
    .toggle button{border:0;background:transparent;padding:6px 12px;border-radius:999px;font-weight:700;cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff}

    .cards{display:flex;gap:18px;padding:18px}
    .plan{background:var(--card);padding:18px;border-radius:14px;box-shadow:var(--shadow);flex:1;min-width:0}
    .plan h3{margin:0 0 8px 0}
    .price{font-size:28px;font-weight:800;color:#222}
    .per{color:var(--muted);font-size:13px}
    .list{margin:12px 0 18px 0;color:var(--muted);line-height:1.5}
    .cta{display:inline-block;padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#6fbf95);color:#fff;text-decoration:none;font-weight:700}

    footer{padding:18px 28px;color:var(--muted);font-size:13px}

    /* small screens */
    @media (max-width:900px){.hero{grid-template-columns:1fr;}.cards{flex-direction:column}}
  </style>
</head>
<body>
  <header>
    <div class="logo"><div class="dot">A</div><div style="line-height:1"><div style="font-weight:800">{{BUSINESS_NAME}}</div><div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div></div></div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Shop</a>
      <a href="pricing.html" style="opacity:0.9">Pricing</a>
      <a href="about.html">Story</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero" aria-labelledby="pricing-hero">
      <div>
        <h1 id="pricing-hero">Flexible scent pathways — choose what fits your rhythm</h1>
        <p>Explore subscription rhythms or one-time program packages. Pricing is framed to help you pick the cadence that may support your daily ease.</p>
        <div style="margin-top:18px" class="controls">
          <div class="toggle" role="tablist" aria-label="Billing toggle">
            <button id="monthlyBtn" class="active" aria-pressed="true">Monthly</button>
            <button id="packageBtn" aria-pressed="false">Package</button>
          </div>
          <div style="font-size:13px;color:var(--muted)">Toggle to compare</div>
        </div>
        <div style="margin-top:18px" class="pattern-crest"></div>
      </div>

      <div>
        <div style="background:var(--card);padding:14px;border-radius:12px;box-shadow:var(--shadow)">
          <strong style="display:block">Quick guide</strong>
          <p style="margin:8px 0 0;color:var(--muted)">Pick "Monthly" for rolling scent guidance; pick "Package" for bundled sessions and custom blends delivered as a set.</p>
        </div>
        <div style="margin-top:12px;background:linear-gradient(180deg,#fff,rgba(255,255,255,0.8));padding:12px;border-radius:12px;box-shadow:var(--shadow)">
          <div style="font-weight:700">Compare at a glance</div>
          <div style="margin-top:10px;display:flex;gap:8px;align-items:center">
            <svg width="40" height="40" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="url(#g)"/></svg>
            <div style="color:var(--muted);font-size:13px">Animated numbers mirror the toggle so you can feel the difference before committing.</div>
          </div>
        </div>
      </div>
    </section>

    <section class="cards" aria-live="polite">
      <div class="plan">
        <h3>Seed Sessions</h3>
        <div class="price" data-month="24" data-package="90">$<span class="num">24</span></div>
        <div class="per">Monthly / or per package (3 sessions)</div>
        <div class="list">A gentle intro: one short consult, a tailored 10ml roll-on, and a micro ritual you can repeat at home.</div>
        <a class="cta" href="book.html">Start with a Seed</a>
      </div>

      <div class="plan">
        <h3>Seasonal Circle</h3>
        <div class="price" data-month="45" data-package="240">$<span class="num">45</span></div>
        <div class="per">Monthly / or per package (4 sessions)</div>
        <div class="list">Ongoing rhythm: monthly check-ins, rotating blends, and scent homework designed for shifting seasons.</div>
        <a class="cta" href="book.html">Join the Circle</a>
      </div>

      <div class="plan">
        <h3>Deepcraft Package</h3>
        <div class="price" data-month="85" data-package="480">$<span class="num">85</span></div>
        <div class="per">Monthly / or per package (8 sessions)</div>
        <div class="list">An immersive arc with custom formulations, extended support, and a small kit to practice at home.</div>
        <a class="cta" href="book.html">Begin Deepcraft</a>
      </div>
    </section>

    <section style="margin:18px;display:flex;gap:18px;align-items:flex-start;flex-wrap:wrap">
      <div style="flex:1;min-width:240px;background:var(--card);padding:16px;border-radius:12px;box-shadow:var(--shadow)">
        <h4 style="margin:0 0 8px 0">Why the two views?</h4>
        <p style="margin:0;color:var(--muted)">Some people prefer a monthly touchpoint; others want a clear package to follow. No medical promises — only sensory practices that may support calmer, steadier routines.</p>
      </div>

      <div style="width:320px;background:linear-gradient(180deg,var(--glass),#fff);padding:16px;border-radius:12px;box-shadow:var(--shadow)">
        <h4 style="margin:0 0 8px 0">Need help choosing?</h4>
        <p style="margin:0 0 12px 0;color:var(--muted)">Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">email us</a>. We offer a brief orientation chat to help you pick a pace.</p>
        <a class="cta" href="contact.html">Ask for a Guide</a>
      </div>
    </section>
  </main>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
      <div>© <strong>{{BUSINESS_NAME}}</strong> — Aromatic practices that may support everyday balance.</div>
      <div style="color:var(--muted)">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
    </div>
  </footer>

  <script>
    // Pricing comparator with animated numbers
    const monthlyBtn = document.getElementById('monthlyBtn');
    const packageBtn = document.getElementById('packageBtn');
    const nums = document.querySelectorAll('.price .num');
    let mode = 'monthly';

    function animateValue(el, start, end) {
      const duration = 600;
      const startTime = performance.now();
      function step(now){
        const progress = Math.min((now - startTime) / duration, 1);
        const value = Math.round(start + (end - start) * easeOutCubic(progress));
        el.textContent = value;
        if(progress < 1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }
    function easeOutCubic(t){return 1 - Math.pow(1 - t, 3)}

    function setMode(newMode){
      if(mode === newMode) return;
      mode = newMode;
      monthlyBtn.classList.toggle('active', mode==='monthly');
      packageBtn.classList.toggle('active', mode==='package');
      monthlyBtn.setAttribute('aria-pressed', mode==='monthly');
      packageBtn.setAttribute('aria-pressed', mode==='package');

      nums.forEach(n =>{
        const priceEl = n.closest('.price');
        const from = parseInt(n.textContent,10);
        const to = parseInt(priceEl.dataset[mode==='monthly' ? 'month' : 'package'],10);
        animateValue(n, from, to);
      });
    }

    monthlyBtn.addEventListener('click',()=>setMode('monthly'));
    packageBtn.addEventListener('click',()=>setMode('package'));
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f9fff8;--muted:#666;--accent:#b7d8c5;--accent-2:#f7d7b1}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:linear-gradient(180deg,var(--bg),#fff);color:#222}
    header{display:flex;justify-content:space-between;padding:18px 28px;align-items:center}
    nav a{margin:0 10px;color:#333;text-decoration:none}
    .wrap{max-width:980px;margin:10px auto;padding:18px}
    .intro{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:start}
    .pill{background:linear-gradient(90deg,var(--accent),var(--accent-2));padding:10px;border-radius:12px;color:#333;font-weight:700}

    .story{background:#fff;padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(11,16,10,0.04)}
    .bio{color:var(--muted);line-height:1.6}

    .mood-tool{margin-top:16px;background:linear-gradient(180deg,#fff,rgba(255,255,255,0.9));padding:14px;border-radius:12px}
    .mood-grid{display:flex;gap:8px;flex-wrap:wrap}
    .mood{padding:10px 12px;border-radius:10px;background:#f6f8f6;border:1px solid #eef3ec;cursor:pointer}
    .mood.active{background:linear-gradient(90deg,#fdf7e9,#eaf7ef);box-shadow:0 6px 18px rgba(11,16,10,.06)}

    .method{margin-top:12px;padding:12px;background:#fff;border-radius:10px}
    .method h4{margin:0}
    .method p{color:var(--muted)}

    footer{margin-top:26px;padding:18px;color:var(--muted)}

    @media (max-width:900px){.intro{grid-template-columns:1fr}.mood-grid{justify-content:space-between}}
  </style>\head>
<body>
  <header>
    <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Services</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Shop</a>
      <a href="pricing.html">Pricing</a>
      <a href="about.html" style="opacity:0.9">Story</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="intro">
      <div class="story">
        <div class="pill">Slow scent, thoughtful practice</div>
        <h2 style="margin-top:12px">A little about our approach</h2>
        <p class="bio">We blend contemporary aromachology ideas with small, usable rituals. Our offerings are crafted to be safe and approachable. We never promise cures — instead we share sensory tools that may support focus, rest, or steadier emotion. Everything is used with dilution guidance and safety in mind.</p>

        <div class="mood-tool" aria-labelledby="mood-label">
          <div id="mood-label" style="font-weight:700">Mood-to-Method selector</div>
          <div style="margin-top:8px;color:var(--muted)">Pick how you feel; the method and CTA will adapt to a tailored suggestion.</div>
          <div class="mood-grid" id="moodGrid" style="margin-top:10px">
            <div class="mood" data-method="calm" data-cta="Book a Calm Consult">Rattled</div>
            <div class="mood" data-method="sleep" data-cta="Try Bedtime Blend">Tired</div>
            <div class="mood" data-method="lift" data-cta="Explore Uplift Tools">Flat</div>
            <div class="mood" data-method="focus" data-cta="Start a Focus Ritual">Distracted</div>
            <div class="mood" data-method="ground" data-cta="Request Grounding Kit">Unsteady</div>
          </div>

          <div id="methodPanel" class="method" aria-live="polite">
            <h4>Suggested approach</h4>
            <p id="methodCopy">Select a mood to see a recommended pathway. Suggestions include short inhalation rituals, gentle roll-ons, or timed routines that may support steadiness.</p>
            <div style="margin-top:12px"><a id="moodCta" class="cta" style="display:inline-block;padding:8px 12px;background:linear-gradient(90deg,#8bbf9f,#f2c57c);color:#fff;border-radius:8px;text-decoration:none;font-weight:700" href="book.html">{{PRIMARY_CTA_LABEL}}</a></div>
          </div>
        </div>

      </div>

      <aside style="background:#fff;padding:18px;border-radius:12px;box-shadow:0 8px 30px rgba(12,12,12,0.06)">
        <h3 style="margin-top:0">Our promise</h3>
        <p style="color:var(--muted)">We emphasize safety: guidance on dilution, patch testing, and scent safety around children and pets. We also provide notes for pregnancy and recommend consulting medical providers when relevant.</p>
        <div style="margin-top:10px;font-size:13px;color:var(--muted)">
          <strong>Safety notes</strong>
          <ul style="margin:8px 0 0 18px">
            <li>Always dilute essential oils. Typical dilution ranges are provided.</li>
            <li>Patch test new blends on a small skin area before regular use.</li>
            <li>Some oils are not recommended in pregnancy or around sensitive pets—check guidance or ask us.</li>
          </ul>
        </div>
      </aside>
    </section>

    <section style="margin-top:20px">
      <h3>Practice snapshots</h3>
      <p style="color:var(--muted)">Short rituals, clear steps. Each suggestion is framed for safe home use and may support small shifts in mood.</p>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px">
        <div style="background:#fff;padding:12px;border-radius:10px">2-min grounding breath + eucalyptus mist</div>
        <div style="background:#fff;padding:12px;border-radius:10px">Bedtime roll-on with diluted lavender and carrier</div>
        <div style="background:#fff;padding:12px;border-radius:10px">Focused desk ritual with citrus inhale and short movement</div>
      </div>
    </section>

    <section style="margin-top:22px;background:#fff;padding:16px;border-radius:12px">
      <h3 style="margin-top:0">FAQ — Safety & practicalities</h3>
      <div style="color:var(--muted)">
        <p><strong>Dilution:</strong> We recommend dilution for topical use. Typical guidance is 1–3% for everyday use; lower for sensitive skin and children.</p>
        <p><strong>Patch test:</strong> Apply a diluted drop on the inner forearm, wait 24 hours to check for reaction.</p>
        <p><strong>Pets:</strong> Some essential oils can be irritating to animals. Use diffusion with caution, limit exposure, and avoid direct application to pets.</p>
        <p><strong>Pregnancy:</strong> Certain oils are not advised during pregnancy. We provide alternatives and note contraindicated oils; consult your provider for concerns.</p>
      </div>
    </section>

  </main>

  <footer>
    <div style="max-width:980px;margin:12px auto;padding:0 18px;color:var(--muted)">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>

  <script>
    // Mood-to-Method interactivity (updates CTA text and method copy)
    const moodGrid = document.getElementById('moodGrid');
    const methodCopy = document.getElementById('methodCopy');
    const moodCta = document.getElementById('moodCta');
    const moods = document.querySelectorAll('.mood');

    const map = {
      calm: {title:'Short calming consult', copy:'A brief consult + a small roll-on with dilution guidance. Great for fast grounding routines that may support steadiness.'},
      sleep: {title:'Evening ritual', copy:'Bedtime blend with careful dilution, timed inhalation, and environmental tips that may support easier sleep cycles.'},
      lift: {title:'Citrus uplift', copy:'An uplifting blend and quick inhalation practice designed to brighten a sluggish afternoon without overstimulation.'},
      focus: {title:'Focus toolkit', copy:'A short desk ritual pairing a focused inhalation with micro-breaks to support concentration.'},
      ground: {title:'Grounding kit', copy:'A small kit with earthy notes and a 15-minute grounding sequence to encourage steadier moments at home.'}
    };

    moodGrid.addEventListener('click', (e)=>{
      const target = e.target.closest('.mood');
      if(!target) return;
      moods.forEach(m=>m.classList.remove('active'));
      target.classList.add('active');
      const method = target.dataset.method;
      const ctaText = target.dataset.cta;
      // animate copy change
      methodCopy.style.opacity = 0;
      setTimeout(()=>{
        methodCopy.textContent = map[method].copy;
        moodCta.textContent = ctaText;
        moodCta.href = 'book.html?method='+encodeURIComponent(method);
        methodCopy.style.opacity = 1;
      },180);
    });

    // set default (none) — keep primary CTA label
    moodCta.textContent = '{{PRIMARY_CTA_LABEL}}';
    moodCta.href = '{{PRIMARY_CTA_URL}}';
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Book a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff7f2;--muted:#666;--accent:#b9e0c9}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:linear-gradient(180deg,var(--bg),#fff);color:#222}
    header{display:flex;justify-content:space-between;padding:14px 22px;align-items:center}
    nav a{margin:0 8px;color:#333;text-decoration:none}
    .container{max-width:920px;margin:20px auto;padding:18px}
    .panel{display:grid;grid-template-columns:1fr 340px;gap:18px}
    .form{background:#fff;padding:18px;border-radius:12px;box-shadow:0 8px 30px rgba(11,16,10,0.06)}
    label{display:block;margin-top:10px;font-size:14px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e6e6e6;margin-top:6px}
    .submit{margin-top:12px;padding:12px 14px;border-radius:10px;background:linear-gradient(90deg,#8bbf9f,#f2c57c);color:#fff;border:0;font-weight:700;cursor:pointer}

    .sidebar{background:#fff;padding:18px;border-radius:12px}
    .guide{color:var(--muted);line-height:1.5}

    .mood-chooser{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
    .mood{padding:8px 10px;border-radius:8px;background:#f7faf7;border:1px solid #eef6ed;cursor:pointer}
    .mood.active{background:linear-gradient(90deg,#fff7e6,#eaffef);box-shadow:0 8px 20px rgba(11,16,10,0.06)}

    @media (max-width:920px){.panel{grid-template-columns:1fr}.sidebar{order:-1}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Services</a>
      <a href="pricing.html">Pricing</a>
      <a href="about.html">Story</a>
      <a href="book.html" style="opacity:0.9">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="container">
    <h1 style="margin-top:0">Reserve a session or request a kit</h1>
    <p style="color:var(--muted)">Choose a simple intake to help us prepare. All sessions include safety guidance and dilution notes.</p>

    <section class="panel">
      <form class="form" id="bookingForm" action="" onsubmit="return handleSubmit(event)">
        <h3 style="margin-top:0">Booking details</h3>
        <label for="name">Full name</label>
        <input id="name" name="name" required />

        <label for="email">Email</label>
        <input id="email" name="email" type="email" required />

        <label for="phone">Phone</label>
        <input id="phone" name="phone" type="tel" />

        <label for="mood">How are you feeling today?</label>
        <div class="mood-chooser" id="moodChooser">
          <div class="mood" data-method="calm" data-cta="Book Calm Consult">Rattled</div>
          <div class="mood" data-method="sleep" data-cta="Try Bedtime Blend">Tired</div>
          <div class="mood" data-method="lift" data-cta="Explore Uplift Tools">Flat</div>
          <div class="mood" data-method="focus" data-cta="Start Focus Ritual">Distracted</div>
        </div>

        <label for="notes">Notes (allergies, pregnancy, pets, preferences)</label>
        <textarea id="notes" name="notes" rows="4" placeholder="Mention any pregnancy, pets, or sensitivities"></textarea>

        <input type="hidden" id="selectedMethod" name="method" />
        <button class="submit" id="bookCta">{{PRIMARY_CTA_LABEL}}</button>
      </form>

      <aside class="sidebar">
        <h4 style="margin-top:0">What to expect</h4>
        <p class="guide">A 30–60 minute session delivered virtually or in-person depending on your selection. We discuss safety, dilution, and give a short ritual to practice. No promises — practices may support calm or clearer focus for some people.</p>

        <div style="margin-top:12px">
          <strong>Quick note</strong>
          <p style="margin:6px 0 0;color:var(--muted)">If pregnant or nursing, list it in notes; we'll suggest safe alternatives. If you keep pets, mention species so we can recommend diffusion strategies.</p>
        </div>
      </aside>
    </section>

    <section style="margin-top:18px;background:#fff;padding:14px;border-radius:12px">
      <h4 style="margin-top:0">Privacy & follow-up</h4>
      <p style="color:var(--muted)">We don’t share your details. After booking you'll receive a short intake confirmation and safety guidance to review before your session.</p>
    </section>

  </main>

  <footer style="padding:12px 22px;color:var(--muted)">Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></footer>

  <script>
    // Mood-to-Method selector (also updates CTA text)
    const chooser = document.getElementById('moodChooser');
    const moods = chooser.querySelectorAll('.mood');
    const selectedMethod = document.getElementById('selectedMethod');
    const bookCta = document.getElementById('bookCta');

    chooser.addEventListener('click', e =>{
      const m = e.target.closest('.mood');
      if(!m) return;
      moods.forEach(x=>x.classList.remove('active'));
      m.classList.add('active');
      const method = m.dataset.method;
      const cta = m.dataset.cta;
      selectedMethod.value = method;
      // small morph animation on button text
      bookCta.style.transform = 'scale(.98)';
      setTimeout(()=>{ bookCta.textContent = cta; bookCta.style.transform = 'scale(1)'; }, 160);
    });

    function handleSubmit(e){
      e.preventDefault();
      const form = e.target;
      const data = new FormData(form);
      // Simple client-side validation for pregnancy/pets note (informational only)
      const notes = data.get('notes') || '';
